import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns overdue invoices', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const invoices = [inv1];
  const report = overdueInvoices(invoices, '2026-10-20');
  assert.equal(report.length, 1);
  assert.equal(report[0].number, inv1.number);
  assert.equal(report[0].daysOverdue, 5);
});

test('overdueInvoices filters by status', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  }).value;

  const paid = JSON.parse(JSON.stringify(inv1));
  paid.status = 'paid';

  const invoices = [inv1, draft, paid];
  const report = overdueInvoices(invoices, '2026-10-20');
  assert.equal(report.length, 1);
  assert.equal(report[0].number, inv1.number);
});

test('overdueInvoices includes partially_paid', () => {
  let inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  inv = recordPayment(inv, { amount: 5000, date: '2026-10-15' }).value;

  const invoices = [inv];
  const report = overdueInvoices(invoices, '2026-10-20');
  assert.equal(report.length, 1);
  assert.equal(report[0].number, inv.number);
});

test('overdueInvoices filters by dueDate', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-10',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const invoices = [inv1];
  const report = overdueInvoices(invoices, '2026-10-24');
  assert.equal(report.length, 0);
});

test('overdueInvoices includes invoice with dueDate exactly at asOf', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const invoices = [inv1];
  const report = overdueInvoices(invoices, '2026-10-15');
  assert.equal(report.length, 0);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET7',
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-10',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET7',
    }).value,
    ['INV-2026-0001']
  ).value;

  const invoices = [inv2, inv1];
  const report = overdueInvoices(invoices, '2026-10-25');
  assert.equal(report.length, 2);
  assert.equal(report[0].daysOverdue, 10);
  assert.equal(report[1].daysOverdue, 7);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const invoices = [inv];
  const report = overdueInvoices(invoices, '2026-10-31');
  assert.equal(report.length, 1);
  assert.equal(report[0].daysOverdue, 16);
});

test('overdueInvoices includes invoice details', () => {
  const inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const invoices = [inv];
  const report = overdueInvoices(invoices, '2026-10-20');
  assert.equal(report.length, 1);
  const item = report[0];
  assert.equal(item.number, inv.number);
  assert.equal(item.customerId, 'C-001');
  assert.equal(item.dueDate, '2026-10-15');
  assert.equal(typeof item.daysOverdue, 'number');
  assert.equal(typeof item.due, 'number');
});

test('overdueInvoices calculates due amount', () => {
  let inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const totalDue = 8500 + Math.round(8500 * 0.21);
  const payment = 3000;
  inv = recordPayment(inv, { amount: payment, date: '2026-10-10' }).value;

  const invoices = [inv];
  const report = overdueInvoices(invoices, '2026-10-20');
  assert.equal(report.length, 1);
  assert.equal(report[0].due, totalDue - payment);
});

test('overdueInvoices handles empty list', () => {
  const report = overdueInvoices([], '2026-10-31');
  assert.equal(report.length, 0);
});

test('overdueInvoices handles multiple overdue with different durations', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET7',
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET7',
    }).value,
    ['INV-2026-0001']
  ).value;

  const invoices = [inv1, inv2];
  const report = overdueInvoices(invoices, '2026-10-31');
  assert.equal(report.length, 2);
  assert.equal(report[0].number, inv1.number);
  assert.equal(report[0].daysOverdue, 46);
  assert.equal(report[1].number, inv2.number);
  assert.equal(report[1].daysOverdue, 9);
});

