test('overdueInvoices calculates due amount', () => {
  let inv = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-01',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const totalDue = 8500 + Math.round(8500 * 0.21);
  const payment = 3000;
  const paymentResult = recordPayment(inv, { amount: payment, date: '2026-10-10' });
  assert.equal(paymentResult.ok, true);
  inv = paymentResult.value;

  const invoices = [inv];
  const report = overdueInvoices(invoices, '2026-10-25');
  assert.equal(report.length, 1);
  assert.equal(report[0].due, totalDue - payment);
});

